def resolve(path, cwd, links):
    def normalize_path(p):
        """Split path into components, handling leading slash."""
        if p.startswith('/'):
            return p[1:].split('/') if len(p) > 1 else []
        else:
            return p.split('/') if p else []

    def path_to_canonical(components):
        """Convert component list to canonical absolute path."""
        if not components:
            return '/'
        return '/' + '/'.join(components)

    # Start with initial path
    if path.startswith('/'):
        current_components = normalize_path(path)
    else:
        current_components = normalize_path(cwd) + normalize_path(path)

    link_count = 0
    max_links = 8

    # Process components left to right
    i = 0
    while i < len(current_components):
        component = current_components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current_components:
                current_components.pop()
            i += 1
            continue

        # Any other name is appended
        current_components = current_components[:i+1]
        current_path = path_to_canonical(current_components)

        # Check if this is a symlink
        if current_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the target and resolve it
            target = links[current_path]
            target_components = normalize_path(target)

            if target.startswith('/'):
                # Absolute target: replace current path
                current_components = target_components
            else:
                # Relative target: relative to the directory containing the link
                current_components = current_components[:-1] + target_components

            # Reset to process from the beginning of the newly resolved path
            i = 0
            continue

        i += 1

    result = path_to_canonical(current_components)
    return result

